"""Entire prime number library and iteration header, source-based contracts."""
def register(topic,q,detail):
 def lesson(title,path,symbol,why,principle,use,reading,qa,cards):
  topic(title,'라이브러리·알고리즘',path,symbol,why,principle,use,reading,*(q(*x) for x in qa),details=[detail(*x) for x in cards])
 def lib(title,symbol,why,principle,use,reading,qa,cards):
  lesson(title,'lib/math/prime_numbers.c',symbol,why,principle,use,reading,qa,cards)
 lib('소수 캐시 구조·비트 번호가 정수 값','primes',
  '숫자 집합을 객체 리스트 대신 비트맵으로 저장하는 소수 라이브러리의 실제 저장 구조를 배웁니다.',
  'struct primes는 rcu_head, last, sz, 가변 길이 unsigned long primes[]를 담습니다. bit x가 켜져 있으면 x가 소수입니다. sz는 비트 영역의 끝이고 last는 가장 큰 저장 소수라 서로 다릅니다. 작은 시작 캐시는 long64에서 sz64,last61, long32에서 sz32,last31이며 0과1 비트는 꺼져 있습니다.',
  '비트 번호와 객체 배열 인덱스를 연결해 읽습니다. 검사 가능한 범위는 x<sz이고 다음 소수를 반드시 찾을 수 있는 조건은 x<last입니다. 두 경계를 같은 값으로 간주하지 않습니다.',
  'struct primes와 두 small_primes 초기화 분기를 읽으세요.',
  [('long64 시작 캐시의 sz64와 last61의 차이는?','범위 끝과 가장 큰 저장 소수의 차이다','둘 다 소수 개수를 뜻한다','sz는 비트 개수이며 last는 그 범위에서 마지막 소수의 숫자입니다. 64와61은 객체 수가 아닙니다.'),('소수 7의 저장 위치는?','비트맵의 bit7이다','일곱 번째 소수 객체 포인터다','이 구조는 숫자를 비트 번호로 사용하는 집합입니다. 0과1은 소수가 아니므로 비트가 꺼져 있습니다.')],
  [('가변 배열','캐시를 확장할 때 구조체 본체 뒤에 bitmap_size(sz) 바이트를 추가 할당합니다. rcu_head는 뒤에 붙는 객체가 아니라 해제 지연 관리 필드입니다.'),('작은 캐시','small_primes는 정적 데이터입니다. 동적으로 확장한 캐시와 같은 방식으로 kfree하면 안 됩니다.')])
 lib('느린 소수 판정·제곱근 아래 약수 검사','slow_is_prime_number',
  '소수 판정에서 검사할 약수를 제곱근까지 줄이는 이유와 느린 fallback의 실행 비용을 배웁니다.',
  'slow_is_prime_number는 int_sqrt(x)에서 시작해 y>1인 동안 x%y를 검사하고 내려갑니다. 합성수 x=a*b이면 적어도 한 인수가 sqrt(x) 이하이므로 해당 구간에 약수가 있습니다. 약수가 없어서 y==1이면 true입니다. x0은 y0이라 false,x1은 y1이라 true가 되는 내부 helper이므로 일반 공개 함수의0·1 캐시 판정과 구분해야 합니다.',
  '할당 실패 후 캐시 밖의 입력에 적용되는 trial division을 읽습니다. 공개 is_prime_number(1)는 시작 캐시 bit1을 읽어 false입니다. 내부 helper의 모든 입력 의미가 공개 계약과 동일하다고 추측하지 않습니다. 큰 소수에서는 매우 오래 걸릴 수 있습니다.',
  'int_sqrt·x%y·y--·return y==1을 추적하세요.',
  [('x가 합성수일 때 제곱근 이하 약수가 필요한 이유는?','두 인수 모두 제곱근보다 크면 곱이 x보다 커지기 때문이다','소수는 모든 작은 수의 배수이기 때문이다','x=a*b에서 두 인수가 모두 sqrt(x)보다 클 수는 없습니다. 작은 인수 검사로 합성수를 찾을 수 있습니다.'),('내부 slow helper가 1에 true이면 공개 함수도 1에 true인가?','아니며 공개 함수는 시작 캐시 bit1에서 false를 얻는다','모든 입력에 항상 동일 경로를 사용한다','공개 함수는 캐시 범위를 먼저 확인합니다. 내부 함수의 특수 입력 동작과 공개 계약을 구분합니다.')],
  [('순서','이 구현은 작은 약수부터가 아니라 floor sqrt에서 내려갑니다. 같은 trial division이라도 조기 종료 비용은 입력에 따라 다릅니다.'),('한계','큰 unsigned long 소수에 대한 fallback은 빠른 Miller–Rabin 같은 알고리즘이 아닙니다. 검사는 실제 숫자 범위를 제한해 실행했습니다.')])
 lib('다음 소수 fallback·엄격히 큰 값과 ULONG_MAX sentinel','slow_next_prime_number',
  '정상 결과와 탐색 끝을 나타내는 sentinel이 같은 숫자 형식으로 반환되는 API를 배웁니다.',
  'slow_next_prime_number는 x<ULONG_MAX인 동안 ++x 후 소수 판정을 반복합니다. 정상 결과는 입력보다 엄격히 큰 소수입니다. 더 진행할 수 없으면 ULONG_MAX를 반환하며 원문 주석은 이를 sentinel이라고 명시합니다. ULONG_MAX를 반환했다고 그 값이 수학적으로 소수라고 주장하면 안 됩니다. 최대 입력에서는 증가를 하지 않습니다.',
  '다음 숫자를 사용하는 호출자는 탐색 끝·수치 범위를 함께 확인합니다. next_prime_number(7)은7이 아닌11입니다. ULONG_MAX 부근에서 unsigned wrap으로0부터 다시 탐색하는 계약이 아닙니다.',
  '증가 위치·while 상한·public next_prime_number 주석의 sentinel 문장을 읽으세요.',
  [('next_prime_number(7)의 정상 결과는?','11이다','7이다','다음 결과는 입력보다 큰 소수입니다. 현재 값 자체가 소수여도 그대로 반환하는 lower bound API가 아닙니다.'),('ULONG_MAX 반환값이 언제나 실제 소수임을 보장하는가?','아니며 탐색 끝 sentinel일 수 있다','이 값은 모든 ABI에서 소수다','원문은 최종 상한을 sentinel로 보고합니다. 결과 값과 수학적 소수 판정을 별도로 이해해야 합니다.')],
  [('상한 검사','원문 실행 검사에서 ULONG_MAX와 ULONG_MAX-1의 다음 결과가 sentinel인지 확인했습니다. 대형 입력 전체 성능을 측정한 것은 아닙니다.'),('0과1','다음 값을 찾는 공개 함수는 작은 캐시에서 정상적으로2를 찾습니다. 내부 helper의1 특수값을 다음 소수의 의미로 확대하지 않습니다.')])
 lib('체의 배수 제거·이전 캐시 구간 보존','clear_multiples',
  '에라토스테네스의 체를 새로 늘어난 비트 구간에 적용하는 배수 시작점 계산을 배웁니다.',
  'clear_multiples는 m=2*x로 소수 자기 자신을 제외합니다. 이 값이 start보다 작으면 roundup(start,x)로 새 구간 첫 배수부터 시작합니다. m<end 동안 bit m을 지우고 m+=x로 이동합니다. 구간은 start 포함,end 제외이며 반환은 마지막 지운 값이 아니라 입력 x입니다.',
  '기존 캐시 [0,start)는 복사해 보존하고 [start,end)의 후보를 제거하는 흐름을 추적합니다. start64,x3이면 첫 제거는66입니다. 일반 수치 함수처럼 모든 unsigned long 극단값에서 곱·roundup이 무조건 안전하다고 가정하지 않습니다.',
  '2*x·roundup·m<end·return x를 읽으세요.',
  [('start64,x3이면 첫 새 구간 배수는?','66이다','64다','64는3의 배수가 아닙니다. roundup은 시작 이상인 첫 배수로 올려 새 구간을 검사합니다.'),('clear_multiples가 반환하는 값은?','입력 x다','마지막으로 제거한 배수다','호출부는 이 반환값을 new->last에 넣습니다. 함수 이름만 보고 반환 의미를 추측하지 않습니다.')],
  [('예제','x5,start64,end80이면65,70,75를 지웁니다. 80은 end 제외 조건이라 이 구간에서는 지우지 않습니다.'),('검증 범위','독립 검사에서 각 확장 캐시의 모든 비트를 trial division 기준과 비교했습니다. 최대 크기 부근의 산술·할당 안전성을 보편 증명한 것은 아닙니다.')])
 lib('캐시 확장·두 배 크기와 실패 시 대체 경로','expand_to_next_prime',
  '수학적 크기 선택·메모리 할당·비트맵 반올림이 함께 쓰이는 실제 확장 경로를 배웁니다.',
  'expand_to_next_prime은 sz=2*x를 계산하고 sz<x이면 wrap을 감지해 false로 끝냅니다. sz를 BITS_PER_LONG 배수로 올리고 구조체+비트맵을 kmalloc합니다. 메모리 실패도 false입니다. 원문은 x보다 크고2*x보다 작은 소수 존재에 관한 Bertrand 정리를 크기 선택 이유로 설명합니다. 첫 곱의 wrap 검사 하나가 이후 round_up·전체 할당 산술의 모든 극단 범위를 자동 증명하지는 않습니다.',
  '정상적인 제한 범위에서 캐시를 확대하고 실패하면 느린 탐색으로 넘어가는 호출부를 읽습니다. GFP_KERNEL 할당은 잠들 수 있으므로 이 함수들을 임의 atomic/IRQ 문맥에서 호출해도 된다고 추측하지 않습니다.',
  'sz 계산·round_up·kmalloc flags·false 반환과 두 공개 호출부를 읽으세요.',
  [('캐시 kmalloc 실패 시 공개 함수는 어떻게 계속하는가?','느린 trial division 경로로 넘어간다','항상 결과0을 소수로 반환한다','확장은 bool로 성공 여부를 알립니다. 호출부는 실패 시 해당 느린 판정 또는 다음 소수 탐색을 실행합니다.'),('2*x wrap 검사만으로 이후 모든 크기 산술 안전성이 증명되는가?','아니며 반올림·할당 크기도 따로 봐야 한다','한 번 검사하면 모든 후속 식도 checked 산술이 된다','각 식의 타입·범위·상한을 따로 판단합니다. 이 원문은 모든 계산에 checked helper를 사용하는 구조가 아닙니다.')],
  [('수학 설명의 위치','소수 존재 정리는 충분한 새 범위를 고르는 배경입니다. allocator 성공이나 기계 정수 산술의 모든 경계를 보장하는 정리는 아닙니다.'),('실제 실패 경로','검증 문맥에서 kmalloc을 강제로 실패시켜64..1499의 공개 결과를 독립 기준과 비교했습니다. 실제 메모리 압박을 일으키지는 않았습니다.')])
 lib('확장 체 실행·복사한 구간과 새 후보 비트','expand_to_next_prime',
  '전체를 참으로 채운 후보 집합에서 합성수를 지워 소수 집합을 만드는 구체적인 반복 순서를 배웁니다.',
  '새 비트맵을 전부 켠 뒤 기존 p->sz 구간을 bitmap_copy합니다. y2부터 켜진 다음 비트를 find_next_bit로 찾으며 새 구간의 배수를 지웁니다. 지워진 합성수는 다음 y 후보에서 건너뜁니다. 반복은 y<sz까지 진행하며 각 y를 new->last에 기록합니다. 이 구현의 반복 범위를 교과서의 sqrt까지만 체질하는 최적화와 같다고 설명하면 원문을 놓칩니다.',
  '작은 캐시에서 확장할 때0·1의 꺼진 비트가 기존 구간 복사로 보존되는 것을 관찰합니다. 새 범위의 모든 비트를 독립 소수 판정과 대조하고 last가 실제 마지막 켜진 소수인지 확인합니다.',
  'bitmap_fill→bitmap_copy→find_next_bit→clear_multiples→new->sz를 읽으세요.',
  [('새 비트맵을 fill하면0과1도 공개 결과에서 소수로 바뀌는가?','아니며 기존 구간 복사로 꺼진 비트가 보존된다','fill 이후에는 어떤 비트도 다시 바꾸지 않는다','기존 캐시 범위는 복사되고 새 후보 구간에서 배수 제거가 실행됩니다. 연산 순서가 집합 의미를 유지합니다.'),('이 원문의 y 반복 조건은?','y<sz다','항상 y*y<=sz만 검사한다','원문 for 조건을 확인합니다. 수학적으로 가능한 다른 최적화와 실제 구현을 구분합니다.')],
  [('예제','3의 새 구간 배수를 지우면66,69 등은 후보에서 빠집니다. find_next_bit는 남아 있는 수를 다음 소수 후보로 사용합니다.'),('컴파일 관찰','독립 GCC 문맥은 new->last 초기화를 loop에서 증명하지 못해 maybe-uninitialized 경고를 냈습니다. 경고를 남겨 두고 유효 확장 검사를 최적화·sanitizer로 실행했으며 모든 극단 경로 안전성 증명으로 확대하지 않습니다.')])
 lib('동시 확장 조정·할당 후 mutex 재검사','expand_to_next_prime',
  '비용이 있는 작업 뒤 잠금을 얻었을 때 상태를 다시 확인해야 하는 실제 이유를 배웁니다.',
  '메모리 할당은 mutex_lock 전에 수행합니다. 잠금을 얻은 뒤 현재 primes를 다시 읽어 x<p->last이면 다른 확장이 이미 충분한 캐시를 공개한 상황이므로 새 할당을 kfree하고 성공 반환합니다. 이전 포인터를 잠금 전부터 신뢰하는 구조가 아닙니다. 보호된 캐시 읽기는 rcu_dereference_protected와 lockdep_is_held 조건을 사용합니다.',
  '할당 성공과 실제 설치 성공을 구분하고 모든 분기의 unlock을 추적합니다. 재검사에서 더 이상 필요 없는 new를 해제하는 것은 누수가 아니라 경쟁 후 불필요한 작업을 정리하는 동작입니다.',
  '할당 위치·mutex_lock·현재 포인터 읽기·x<p->last·goto unlock을 읽으세요.',
  [('할당 후 재검사에서 현재 캐시가 이미 충분하면?','new를 해제하고 기존 캐시를 유지한다','항상 더 작은 새 캐시로 덮어쓴다','잠금 전 할당 중 상태가 바뀔 수 있습니다. 현재 보호된 상태를 기준으로 불필요한 설치를 피합니다.'),('rcu_dereference_protected 조건이 mutex를 자동 획득하는가?','아니며 이미 얻은 보호 조건을 나타낸다','조건 식이 모든 writer를 대신 잠근다','mutex_lock은 별도 호출입니다. 보호 검사와 잠금 획득을 구분해야 합니다.')],
  [('순차 재현','큰 캐시 설치 후 작은 x로 expand를 호출해 new가 할당·해제되고 기존 캐시가 보존되는 경로를 확인했습니다.'),('경쟁 검사 한계','현재 fixture는 mutex/RCU를 순차 상태 모델로 제공합니다. 실제 여러 writer의 스케줄·메모리 순서를 검증한 것은 아닙니다.')])
 lib('캐시 공개와 RCU 해제·정적 시작 캐시 예외','free_primes',
  '새 캐시로 바꿔도 기존 독자가 이전 메모리를 읽을 수 있는 자료구조에서 해제를 지연하는 원리를 배웁니다.',
  '확장 설치는 rcu_assign_pointer(primes,new)로 새 캐시를 공개한 뒤 이전 p가 small_primes가 아닐 때 kfree_rcu로 해제를 지연합니다. free_primes도 mutex 아래 동적 캐시를 small_primes로 되돌리고 이전 동적 메모리를 지연 해제합니다. 정적 small_primes는 해제 대상이 아닙니다. 포인터 교체만으로 기존 독자가 종료된 것은 아닙니다.',
  'reader가 포인터를 읽고 비트를 검사하는 구간과 writer가 캐시를 교체하는 구간을 연결합니다. 일반 kfree로 즉시 이전 캐시를 없애면 기존 독자 수명 계약을 깨뜨릴 수 있습니다.',
  '설치부와 free_primes의 정적 포인터 비교·공개·kfree_rcu를 비교하세요.',
  [('이전 캐시를 즉시 kfree하지 않는 이유는?','기존 RCU 독자가 이전 캐시를 사용 중일 수 있어서다','새 캐시가 이전 캐시 메모리를 항상 공유해서다','캐시 교체는 새로운 독자에게 보이는 포인터를 바꾸지만 이미 읽은 포인터의 수명을 끝내지 않습니다.'),('small_primes도 kfree_rcu로 해제하는가?','아니며 정적 시작 캐시는 제외한다','모든 포인터를 반드시 같은 방식으로 해제한다','원문은 p!=&small_primes를 검사합니다. 정적 저장 객체와 동적 할당 객체의 소유권이 다릅니다.')],
  [('재사용','정리 후에도 공개 포인터는 유효한 작은 캐시를 가리킵니다. NULL 캐시로 바꿔 모든 조회를 중단하는 동작이 아닙니다.'),('모델 범위','fixture의 지연 해제는 독자가 없는 순차 시점에서 처리됩니다. 실제 커널 RCU grace period 실행의 증거가 아닙니다.')])
 lib('공개 다음 소수 조회·last 경계와 RCU 재진입','next_prime_number',
  '캐시 범위 확장이 필요한 조회에서 읽기 구간을 나갔다가 다시 들어가는 제어 흐름을 배웁니다.',
  'next_prime_number는 RCU 읽기 보호를 얻고 현재 캐시를 읽습니다. x>=p->last이면 읽기 보호를 풀고 확장을 시도합니다. 성공 후 다시 보호를 얻어 현재 포인터를 읽고 조건을 반복합니다. 정상 조회는 x+1부터 p->last를 경계로 find_next_bit합니다. find_next_bit의 경계까지 못 찾은 반환값도 마지막 소수 last와 일치하는 문맥입니다.',
  'x61,초기 last61이면 확장이 필요하고,x60이면61을 돌려주는 흐름을 추적합니다. 보호 밖에서 오래된 p를 계속 쓰지 않고 재진입 후 포인터를 갱신하는 이유를 설명합니다.',
  'while의 unlock→expand→lock→dereference와 마지막 find_next_bit를 읽으세요.',
  [('초기 long64 캐시에서 next_prime_number(61)은 확장이 필요한가?','필요하며61보다 큰 소수를 찾아야 한다','61 자체를 즉시 돌려주므로 필요 없다','입력보다 큰 결과가 필요합니다. 조건 x>=last는 캐시에 더 큰 소수가 보장되지 않는 상태를 감지합니다.'),('확장 후 이전 p를 그대로 재사용하는가?','아니며 다시 RCU 보호를 얻고 현재 포인터를 읽는다','할당 전 p가 항상 최신이다','writer가 포인터를 바꿀 수 있으므로 재진입 후 현재 캐시를 읽어 조건을 다시 확인합니다.')],
  [('성공 재검사','확장 성공은 충분한 현재 캐시를 기대하지만 호출부는 while로 조건을 다시 봅니다. 다른 writer 문맥과 함께 읽습니다.'),('비용','캐시에 있으면 다음 켜진 비트 탐색이고 캐시 밖이면 할당·체 확장 또는 느린 탐색이 추가됩니다.')])
 lib('공개 소수 판정·sz 경계와 bit 조회','is_prime_number',
  '값 하나의 집합 포함 여부와 그보다 큰 다음 값을 찾는 함수가 서로 다른 경계를 쓰는 이유를 배웁니다.',
  'is_prime_number는 x>=p->sz일 때만 확장이 필요합니다. 범위 안에서는 test_bit(x,p->primes)를 반환합니다. 따라서 초기 long64에서62와63은 확장 없이 합성수로 판정할 수 있지만 next_prime_number(62)는 last61보다 커 확장이 필요합니다. 0과1도 작은 캐시의 꺼진 비트로 false입니다.',
  '캐시 범위 포함 검사와 다음 소수 존재 검사를 구분합니다. 할당 실패에서는 slow_is_prime_number로 넘어가므로 반환bool을 메모리 성공 여부로 오해하지 않습니다.',
  'is_prime_number의 sz 조건과 next_prime_number의 last 조건을 비교하세요.',
  [('초기 long64에서 is_prime_number(63)은 확장이 필요한가?','아니며63은 sz64 안에 있다','last61보다 크므로 반드시 확장한다','판정은 비트가 존재하면 가능합니다. 다음 소수 탐색과 달리 더 큰 소수가 캐시에 있어야 할 필요는 없습니다.'),('is_prime_number false가 반드시 메모리 할당 실패를 뜻하는가?','아니며 정상 합성수 판정 결과다','모든 false는 allocator 오류 코드다','공개 반환형은 소수 여부 bool입니다. 할당 실패 시에도 fallback으로 수학적 판정을 시도합니다.')],
  [('반환 계약','0과1은 소수가 아니며 공개 결과는 false입니다. 정상적으로 캐시 bit 조회로 처리됩니다.'),('독립 기준','0..11999의 소수 여부와 다음 소수를 독립 작은 약수 trial division 기준과 비교했습니다.')])
 lesson('소수 순회 매크로·from 첫 값은 필터하지 않는다','include/linux/prime_numbers.h','for_each_prime_number_from',
  '이름이 소수 순회인 매크로에서도 최초 값의 전제와 종료 상한을 직접 확인하는 습관을 배웁니다.',
  'for_each_prime_number는 from2로 시작해2부터 max 포함까지 진행합니다. from 변형은 prime=from을 먼저 본문에 넘기며 최초 from이 소수인지 검사하지 않습니다. from1이면 첫1,from4이면 첫4가 나오고 이후 next_prime_number로 증가합니다. max<ULONG_MAX 조건이 중요하며 max가 sentinel이면 prime가 같은 최대값에 머물러 종료하지 않을 수 있습니다.',
  '모든 본문 값이 소수여야 하면 from도 적절한 소수로 준비하거나 첫 값 처리를 별도로 합니다. 문서가 허용하는1 시작 용례와 일반 소수 집합 순회를 구분합니다. 입력은 한계 내의 안정된 값으로 제공합니다.',
  'prime=(from)·prime<=max·next_prime_number(prime)와 종료 조건 주석을 읽으세요.',
  [('from4로 시작하면 첫 본문 값은?','4다','자동 필터되어5다','초기식은 전달한 from을 그대로 대입합니다. 다음 갱신부터 next_prime_number를 호출합니다.'),('max=ULONG_MAX에서 sentinel에 도달하면 종료가 보장되는가?','아니며 같은 값으로 반복할 수 있다','반복문이 자동으로0으로 돌아 종료한다','조건은 <=max이고 다음 sentinel도 ULONG_MAX입니다. 원문이 요구하는 상한 조건을 지켜야 합니다.')],
  [('정상 예','for_each_prime_number(p,10)은2,3,5,7을 방문합니다. max를 포함하는 조건이지만10은 소수가 아니라 방문하지 않습니다.'),('실제 검사','원문 매크로로100 이하25개 소수와 from1·from4의 최초 값을 확인했습니다. 의도적 무한 반복은 실행하지 않았습니다.')])
 lib('소수 selftest와 모듈 수명·검사가 다루는 범위','selftest',
  '내부 기준과 공개 API를 대조하는 selftest의 범위·실패 진단·정리 경로를 배웁니다.',
  'selftest는 max0이면 생략합니다. x2부터 x<max까지 slow와 공개 판정을 비교하고 소수일 때 이전 last의 next 결과가 x인지 검사합니다. 불일치하면 dump_primes 후 -EINVAL입니다. primes_init은 모듈 파라미터 selftest_max를 쓰고 primes_exit은 free_primes로 정리합니다. dump는 PAGE_SIZE 버퍼를 할당해 캐시를 RCU 구간에서 출력한 뒤 해제합니다.',
  '검사 범위 max가 제외 상한임을 확인하고 max0을 전체 검증 통과로 설명하지 않습니다. 판정 경로가 같은 내부 helper를 재사용하는 한계를 생각합니다. 별도 fixture에서는 독립 약수 기준과 캐시 전체 비트·할당 실패·초기화/종료를 추가 비교했습니다.',
  'selftest·dump_primes·primes_init/exit·module_param_named를 연결해 읽으세요.',
  [('selftest max0이 의미하는 것은?','검사를 생략하고 성공 반환한다','전체 unsigned long을 검사했다','첫 if(!max)return0입니다. 성공 반환과 실제 검사 범위를 별도로 기록해야 합니다.'),('selftest의 x 반복은 max를 포함하는가?','아니며 x<max다','항상 max까지 포함한다','소수 순회 header의 <=max 조건과 다릅니다. 각 함수의 실제 종료식을 확인합니다.')],
  [('진단 한계','dump_primes의 출력 helper·커널 로그·할당 실패 출력 문맥은 별도 기술입니다. 독립 fixture는 진단 출력을 모델링했으며 printk 전체 동작을 증명하지 않습니다.'),('전체 검증','전체 header/C로80,569개 비교를 최적화·ASan/UBSan에서 통과했습니다. 순차 allocator/bitmap/mutex/RCU 모델이며 실제 RCU 경쟁·native32·대형 크기 극단 안전성 검사는 아닙니다.')])
